<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Invoice <?= esc($invoice['invoice_no']) ?></title><style>
@page{size:A4;margin:18mm}*{box-sizing:border-box}body{font-family:"DejaVu Sans",Arial,sans-serif;color:#1e293b;font-size:11px;margin:0}.toolbar{display:flex;justify-content:flex-end;margin:0 auto 14px;max-width:780px}.print-button{background:#356ef2;color:#fff;border:0;border-radius:6px;padding:9px 15px;font-size:11px;cursor:pointer}.sheet{max-width:780px;margin:0 auto;background:#fff}.header{display:flex;justify-content:space-between;gap:25px;border-bottom:2px solid #356ef2;padding-bottom:20px}.brand{max-width:340px}.brand img{max-width:190px;max-height:65px;object-fit:contain}.brand h1{font-size:18px;margin:7px 0}.muted{color:#64748b;line-height:1.6}.invoice-title{text-align:right}.invoice-title h2{font-size:25px;color:#356ef2;letter-spacing:2px;margin:0 0 10px}.invoice-title p{margin:4px 0}.columns{display:flex;justify-content:space-between;gap:35px;margin:25px 0}.columns>div{width:50%;line-height:1.65}.label{color:#64748b;text-transform:uppercase;letter-spacing:.6px;font-size:9px;font-weight:bold;margin-bottom:7px}.columns strong{font-size:12px}.details{display:flex;gap:28px;margin:10px 0 18px}.details div{display:grid;gap:4px}.details span{color:#64748b;font-size:9px}.details strong{font-size:10px}.items{width:100%;border-collapse:collapse;margin:15px 0 20px}.items th{background:#f1f5f9;text-align:left;padding:10px 9px;font-size:9px;text-transform:uppercase}.items td{padding:12px 9px;border-bottom:1px solid #e2e8f0}.right{text-align:right}.totals{width:290px;margin-left:auto}.totals div{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #e2e8f0}.totals .grand{font-size:14px;font-weight:bold;color:#1d4ed8}.paid{margin-top:18px;padding:10px;background:#eff6ff;border-radius:6px}.payments{margin-top:24px;border-top:1px solid #e2e8f0;padding-top:13px}.payments ul{padding-left:16px;color:#475569}.footer{margin-top:45px;padding-top:15px;border-top:1px solid #e2e8f0;text-align:center;color:#64748b;font-size:9px;line-height:1.6}@media print{.toolbar{display:none}.sheet{max-width:none}}
</style></head><body><?php if (empty($pdfMode)): ?><div class="toolbar"><button class="print-button" onclick="window.print()">Cetak invoice</button></div><?php endif; ?><main class="sheet"><header class="header"><div class="brand"><?php if ($logoData): ?><img src="<?= $logoData ?>" alt="Logo"><?php else: ?><h1><?= esc($siteName) ?></h1><?php endif; ?><div class="muted"><?= esc($siteTagline) ?><br><?= nl2br(esc($invoice['branch_address'] ?: '')) ?><br><?= esc($invoice['branch_phone'] ?: $publicPhone) ?></div></div><div class="invoice-title"><h2>INVOICE</h2><p><strong><?= esc($invoice['invoice_no']) ?></strong></p><p>Periode: <?= esc($invoice['period']) ?></p><p>Status: <?= esc(strtoupper($invoice['status'])) ?></p></div></header>
<section class="columns"><div><div class="label">Ditagihkan kepada</div><strong><?= esc($invoice['full_name']) ?></strong><br><?= esc($invoice['customer_code']) ?><br><?= esc($invoice['customer_phone'] ?: '') ?><br><?= nl2br(esc($invoice['customer_address'] ?: '')) ?></div><div><div class="label">Rincian tagihan</div><div class="details"><div><span>Jatuh tempo</span><strong><?= esc($invoice['due_date']) ?></strong></div><div><span>Jenis layanan</span><strong><?= esc(strtoupper($invoice['service_type'] ?? 'INTERNET')) ?></strong></div></div></div></section>
<table class="items"><thead><tr><th>Deskripsi</th><th>Periode</th><th class="right">Jumlah</th></tr></thead><tbody><tr><td><?= esc($invoice['plan_name'] ?: 'Layanan internet') ?></td><td><?= esc($invoice['period']) ?></td><td class="right"><?= esc(mynet_money($invoice['amount'])) ?></td></tr><?php if ((float) $invoice['discount'] > 0): ?><tr><td colspan="2">Diskon</td><td class="right">- <?= esc(mynet_money($invoice['discount'])) ?></td></tr><?php endif; ?></tbody></table>
<div class="totals"><div><span>Subtotal</span><strong><?= esc(mynet_money($invoice['amount'])) ?></strong></div><div><span>Diskon</span><strong><?= esc(mynet_money($invoice['discount'])) ?></strong></div><div class="grand"><span>Total tagihan</span><strong><?= esc(mynet_money($invoice['total'])) ?></strong></div><div><span>Sudah dibayar</span><strong><?= esc(mynet_money($paid)) ?></strong></div><div><span>Sisa</span><strong><?= esc(mynet_money($balance)) ?></strong></div></div>
<?php if ($payments): ?><section class="payments"><strong>Riwayat pembayaran</strong><ul><?php foreach ($payments as $payment): ?><li><?= esc($payment['paid_at'] ?: 'Lunas') ?> · <?= esc($payment['payment_method'] ?: ucfirst($payment['provider'])) ?> · <?= esc(mynet_money($payment['amount'])) ?></li><?php endforeach; ?></ul></section><?php endif; ?>
<footer class="footer">Terima kasih telah menggunakan layanan <?= esc($siteName) ?>. Simpan invoice ini sebagai bukti tagihan.</footer></main></body></html>
